// BenchCBv2RealModel — real-weights validation driver for the
// ContinuousBatchingV2 engine (EngineV2) against the legacy engine
// (Scheduler → EngineCore), per docs/engine-v2/specs/G-harness.md
// "integration re-baselines on real weights".
//
// Loads a LOCAL model directory explicitly through `LLMModelFactory.shared`
// (the registry tries the VLM factory first; text-only Gemma-4 checkpoints
// carry a vision_config + vision tower that would otherwise load the MLXVLM
// Gemma4, which has no CBv2 hooks). One loaded model instance drives every
// engine, so comparisons are same-weights by construction.
//
// Modes:
//   correctness (v2 contiguous, greedy):
//     1. b1-sanity ... chat prompt → coherent text, EOS stop, no repetition.
//     2. invariance .. same prompt solo / B=3 burst (short+long neighbors) /
//                      joining mid-stream — token-exact identical.
//     3. chunked ..... ~1500-token prompt, prefillChunkSize 512 vs
//                      no-chunking — token-exact identical.
//   perf: B ∈ {1,2,4} with mixed prompt lengths (~100/~500/~1500),
//     maxTokens 128, engines v2 (contiguous) / v2-paged. Those are the only
//     engines that can be measured in v0.8.0 — the legacy engine and compiled
//     decode were both removed — so `--engines legacy` / `v2-compiled` emit a
//     visible refusal row instead of a measurement (see `resolveEngine`).
//     --prompt-lengths replaces the mix (cycled to the batch width) and
//     resizes the paged pool's nominalMaxSequenceLength to match, so prompts
//     far above the default 1500 cap are measurable.
//
// Every option is parsed strictly (`BenchOptions.parse`): a malformed value is
// a hard usage error, never a silent fallback to a different experiment.
//
// The report header stamps the revision the *binary* was built from
// (`BenchBuildRevision.value`, generated by Plugins/BenchRevisionStamp) plus a
// shell-escaped argv, so a number always traces back to a reproducible run.
//
// Usage:
//   swift run -c release BenchCBv2 --model <dir> [--mode all|correctness|perf]
//       [--engines v2,v2-paged] [--batches 1,2,4] [--steps 128]
//       [--prompt-lengths 500,10000] [--max-seq-len N] [--label tag]
//       [--kv-gb 16] [--out report.md] [--print-revision]
//
// Target layout: everything below lives in the LIBRARY target BenchCBv2Core;
// the `BenchCBv2` executable is a three-line `@main` shim over
// `BenchCBv2Driver.run()`. That boundary is load-bearing, not cosmetic. A test
// target that depends on an executable target makes SwiftPM run *that binary*
// as the swift-testing host, handing it `--test-bundle-path` — which this
// strict parser rejects, aborting the swift-testing pass for the whole
// package. Every `@Test` in mlx-swift-lm went dark that way. Tests
// `@testable import BenchCBv2Core`; nothing may depend on the executable.

import Foundation
import MLX
import MLXHuggingFace
import MLXLLM
import MLXLMCommon
import Tokenizers

// MARK: - Deterministic PRNG (same SplitMix64 as benchmarks/CBv2Benchmark.swift)

struct BenchRNG: RandomNumberGenerator {
    private var state: UInt64
    init(seed: UInt64) { self.state = seed }
    mutating func next() -> UInt64 {
        state &+= 0x9E37_79B9_7F4A_7C15
        var z = state
        z = (z ^ (z >> 30)) &* 0xBF58_476D_1CE4_E5B9
        z = (z ^ (z >> 27)) &* 0x94D0_49BB_1331_11EB
        return z ^ (z >> 31)
    }
}

/// Synthetic prompt drawn from a "safe" id range (avoids BOS/EOS/control
/// ids at the top and bottom of the vocab) — identical across engines for a
/// given (length, seed).
func syntheticPrompt(length: Int, seed: UInt64, vocabSize: Int) -> [Int] {
    var rng = BenchRNG(seed: seed)
    let upper = min(vocabSize - 1, 50_000)
    return (0 ..< length).map { _ in Int.random(in: 100 ..< upper, using: &rng) }
}

func percentile(_ sorted: [Double], _ q: Double) -> Double {
    guard !sorted.isEmpty else { return 0 }
    let rank = q * Double(sorted.count - 1)
    let lo = Int(rank.rounded(.down)), hi = Int(rank.rounded(.up))
    if lo == hi { return sorted[lo] }
    let w = rank - Double(lo)
    return sorted[lo] * (1 - w) + sorted[hi] * w
}

// MARK: - V2 stack construction

/// Immutable requested/effective topology resolved when the benchmark model
/// is constructed. These values are repeated in every measured cell so a
/// standalone JSON result cannot lose its run-level feature provenance.
struct ModelOptimizationProvenance: Codable, Sendable, Equatable {
    let layer18Requested: Bool
    let layer18Effective: Bool
    let layer18Interval: Int?
    let weightedUnsortRequested: Bool
    let weightedUnsortEffective: Bool
    let safeR1GeometryEligible: Bool

    var markdown: String {
        "layer18(requested=\(layer18Requested), effective=\(layer18Effective), "
            + "interval=\(layer18Interval.map(String.init) ?? "n/a")); "
            + "weightedUnsort(requested=\(weightedUnsortRequested), "
            + "effective=\(weightedUnsortEffective)); "
            + "safeR1GeometryEligible=\(safeR1GeometryEligible)"
    }
}

/// CBv2 structural hooks for the loaded model (layer kinds + cache builder,
/// which for GPT-OSS also primes the sinks-activation probe at build time).
struct V2ModelHooks {
    /// Exact model instance driven by EngineV2. For an outer Gemma4Model this
    /// is its owned text tower; all hooks below are derived from this object.
    let model: any LanguageModel
    let layerKinds: [CBv2LayerKind]
    let optimizations: ModelOptimizationProvenance
    let buildCaches:
        (@escaping (Int, CBv2LayerKind) throws -> any CBv2AttendingLayerCache) throws ->
            [any CBv2AttendingLayerCache]
}

func v2Hooks(for model: any LanguageModel) -> V2ModelHooks? {
    if let m = model as? Gemma4Model {
        let textModel = m.textModel
        let interval = textModel.cbv2PrefillChunkEvalInterval
        let layerKinds = textModel.cbv2LayerKinds
        return V2ModelHooks(
            model: textModel,
            layerKinds: layerKinds,
            optimizations: ModelOptimizationProvenance(
                layer18Requested: interval > 0,
                layer18Effective: interval > 0 && layerKinds.count >= interval,
                layer18Interval: interval,
                weightedUnsortRequested: textModel.weightedExpertUnsortRequested,
                weightedUnsortEffective: textModel.weightedExpertUnsortEffective,
                safeR1GeometryEligible: textModel.expertQMMGeometryEligible)
        ) { mk in
            try textModel.newCacheV2(makeLayerCache: mk)
        }
    }
    if let m = model as? Gemma4TextModel {
        let interval = m.cbv2PrefillChunkEvalInterval
        let layerKinds = m.cbv2LayerKinds
        return V2ModelHooks(
            model: m,
            layerKinds: layerKinds,
            optimizations: ModelOptimizationProvenance(
                layer18Requested: interval > 0,
                layer18Effective: interval > 0 && layerKinds.count >= interval,
                layer18Interval: interval,
                weightedUnsortRequested: m.weightedExpertUnsortRequested,
                weightedUnsortEffective: m.weightedExpertUnsortEffective,
                safeR1GeometryEligible: m.expertQMMGeometryEligible)
        ) { mk in
            try m.newCacheV2(makeLayerCache: mk)
        }
    }
    if let m = model as? GPTOSSModel {
        return V2ModelHooks(
            model: m,
            layerKinds: m.cbv2LayerKinds,
            optimizations: ModelOptimizationProvenance(
                layer18Requested: false,
                layer18Effective: false,
                layer18Interval: nil,
                weightedUnsortRequested: false,
                weightedUnsortEffective: false,
                safeR1GeometryEligible: false)
        ) { mk in
            try m.newCacheV2(makeLayerCache: mk)
        }
    }
    return nil
}

/// Paged-pool sizing for the perf cells: `--max-seq-len`, else derived from
/// the longest requested prompt. It only splits pool capacity across layer
/// groups by per-sequence demand — not a hard ceiling — but sizing it below
/// the real prompt length starves the full-attention group while the windowed
/// groups keep their full ring. 4096 is the historical default.
nonisolated(unsafe) var benchPagedNominalMaxSequenceLength = 4096

enum V2Backend: String {
    case contiguous = "v2"
    case paged = "v2-paged"
}

/// How one `--engines` name is served by the perf matrix.
///
/// There are exactly two outcomes, and the invariant that matters for release
/// gating is that a measured row's `engine` label is *always* the rawValue of
/// the backend that actually produced it (`runV2Cell` labels from the
/// `V2Backend` it was handed), so a label can never describe a different
/// execution path than the one measured.
///
/// This is the guard the compiled-decode harness lacked. `v2-compiled` sized
/// its own KV capacity independently of `--prompt-lengths`, and the compiled
/// executor fell back to eager decode once a full-attention row's offset
/// reached that capacity — so `--prompt-lengths 10000 --engines v2-compiled`
/// emitted eager numbers under a `v2-compiled` label. Compiled decode is gone
/// in v0.8.0; the name is still refused explicitly rather than ignored, so the
/// old command can never again produce a silently mislabelled datapoint.
enum EngineResolution: Equatable {
    /// Measure this cell on `backend`; the row is labelled `backend.rawValue`.
    case run(V2Backend)
    /// Emit a visible non-measurement row carrying `reason`.
    case refuse(reason: String)
}

func resolveEngine(_ name: String) -> EngineResolution {
    if let backend = V2Backend(rawValue: name) { return .run(backend) }
    switch name {
    case "v2-compiled":
        return .refuse(
            reason: "refused: compiled decode was removed in v0.8.0 — "
                + "it cannot be measured; use v2")
    case "legacy":
        return .refuse(
            reason: "refused: the legacy engine was removed in v0.8.0 — use v2")
    default:
        return .refuse(reason: "refused: unknown engine")
    }
}

/// Non-measurement row for the perf table. Every metric column is `-`, so a
/// refused cell cannot be read as a datapoint, and the reason is escaped so a
/// `|` in an error description cannot forge extra columns.
func refusalRow(engine: String, reason: String) -> String {
    let safeEngine = markdownCellEscaped(engine)
    let safeReason = markdownCellEscaped(reason)
    return "| \(safeEngine) | - | - | \(safeReason) | - | - | - |"
}

/// Escape a value destined for a markdown table cell: a literal `|` would
/// otherwise split the row, and a newline would terminate it.
func markdownCellEscaped(_ text: String) -> String {
    text.replacingOccurrences(of: "|", with: "\\|")
        .replacingOccurrences(of: "\n", with: " ")
        .replacingOccurrences(of: "\r", with: " ")
}

/// Build a fresh EngineV2 over the (already loaded) model. Throws
/// CBv2KVError.backendIneligible when the paged kernel cannot serve this
/// model/hardware — callers skip gracefully.
func makeV2Engine(
    context: ModelContext, hooks: V2ModelHooks, backend: V2Backend,
    schedulerConfig: CBv2SchedulerConfig, kvBytes: Int
) throws -> EngineV2 {
    let kvBackend: CBv2KVBackend
    let caches: [any CBv2AttendingLayerCache]
    switch backend {
    case .contiguous:
        kvBackend = CBv2ContiguousKVBackend(config: .init(bytesCapacity: kvBytes))
        caches = try hooks.buildCaches { index, kind in
            CBv2LayerCache(layerIndex: index, kind: kind)
        }
    case .paged:
        // Static kernel eligibility (head dims + the part kernel's
        // threadgroup-memory budget) is validated inside
        // `PagedKVBackend.init` — it throws `backendIneligible` before any
        // dispatch could trap. Gemma-4 global layers (headDim 512 / GQA 8)
        // are eligible via the kernel's head split.
        let paged = try PagedKVBackend(
            layerKinds: hooks.layerKinds,
            config: PagedKVPoolConfig(
                capacityBytes: kvBytes,
                maxPrefillChunk: schedulerConfig.prefillChunkSize,
                nominalMaxSequenceLength: benchPagedNominalMaxSequenceLength))
        let pagedCaches = paged.makeLayerCaches()
        // Route through newCacheV2 so GPT-OSS primes its sinks probe.
        caches = try hooks.buildCaches { index, _ in pagedCaches[index] }
        kvBackend = paged
    }
    return EngineV2(
        model: CBv2SteppableLanguageModelAdapter(hooks.model),
        layerKinds: hooks.layerKinds,
        backend: kvBackend,
        cacheProvider: CBv2LayerCacheBank(caches: caches),
        sampler: CBv2DefaultSampler(),
        detokenizerFactory: CBv2TextDetokenizerFactory(tokenizer: context.tokenizer),
        schedulerConfig: schedulerConfig)
}

// MARK: - Request runners

struct RunResult: Sendable {
    var tokens: [Int] = []
    var logprobs: [CBv2TokenLogprob] = []
    var text = ""
    var finish: String = "?"
    var promptTokens = 0
    var completionTokens = 0
    var submittedAt: Double = 0
    var firstTokenAt: Double = 0
    var lastTokenAt: Double = 0
    var finishedAt: Double = 0
    var itlsMs: [Double] = []

    /// 0 when no token ever arrived (errored request).
    var ttftMs: Double { firstTokenAt == 0 ? 0 : (firstTokenAt - submittedAt) * 1e3 }
    /// Steady-state decode TPS (first token excluded — it carries prefill).
    var decodeTPS: Double {
        guard tokens.count > 1, lastTokenAt > firstTokenAt else { return 0 }
        return Double(tokens.count - 1) / (lastTokenAt - firstTokenAt)
    }
}

actor TokenCounter {
    private(set) var count = 0
    func add(_ n: Int) { count += n }
}

func collectV2(
    _ stream: AsyncStream<CBv2Event>, submittedAt: Double, counter: TokenCounter? = nil
) async -> RunResult {
    var r = RunResult()
    r.submittedAt = submittedAt
    var last: Double?
    for await event in stream {
        let now = CFAbsoluteTimeGetCurrent()
        switch event {
        case .delta(let text, let tokens, let logprobs):
            if !tokens.isEmpty {
                if last == nil {
                    r.firstTokenAt = now
                } else {
                    r.itlsMs.append((now - last!) * 1e3)
                }
                last = now
                r.lastTokenAt = now
                r.tokens.append(contentsOf: tokens)
                if let logprobs { r.logprobs.append(contentsOf: logprobs) }
                if let counter { await counter.add(tokens.count) }
            }
            r.text += text
        case .finished(let reason, let usage):
            r.finish = "\(reason)"
            r.promptTokens = usage.promptTokens
            r.completionTokens = usage.completionTokens
            r.finishedAt = now
        }
    }
    if r.finishedAt == 0 { r.finishedAt = CFAbsoluteTimeGetCurrent() }
    return r
}

func runV2Request(
    engine: EngineV2, id: UInt64, promptTokens: [Int], maxTokens: Int, stopTokens: Set<Int>,
    topLogprobs: Int = 0
) async throws -> RunResult {
    let submittedAt = CFAbsoluteTimeGetCurrent()
    let stream = try engine.submit(
        CBv2Request(
            id: CBv2RequestID(id), promptTokens: promptTokens,
            sampling: CBv2SamplingParams(temperature: 0, topLogprobs: topLogprobs),
            maxTokens: maxTokens, stopTokens: stopTokens))
    return await collectV2(stream, submittedAt: submittedAt)
}

/// Human-readable dump of one side's logprob record at the divergence index:
/// the chosen token's raw logprob plus the top alternatives and the gap to
/// the runner-up (a near-zero gap = argmax tie flip from batched-kernel
/// numerics, not an engine logic bug).
func logprobDetail(_ r: RunResult, at index: Int, label: String) -> String {
    guard let lp = r.logprobs[safe: index] else { return "\(label): no logprobs captured" }
    let alts = lp.topLogprobs.prefix(4)
        .map { String(format: "%d:%.4f", $0.token, $0.logprob) }
        .joined(separator: " ")
    var gap = ""
    if lp.topLogprobs.count >= 2 {
        gap = String(format: " gap(top1-top2)=%.5f", lp.topLogprobs[0].logprob - lp.topLogprobs[1].logprob)
    }
    return String(format: "%@: chose %d (logprob %.4f) top=[%@]%@", label, lp.token, lp.logprob, alts, gap)
}

// MARK: - Perf cells

struct RunOptimizationProvenance: Codable, Sendable, Equatable {
    let model: ModelOptimizationProvenance
    let safeR1Requested: Bool
    let safeR1AOTAvailable: Bool
    let safeR1NAXAvailable: Bool
    let safeR1Effective: Bool
}

struct SafeR1Provenance: Codable, Sendable, Equatable {
    let requested: Bool
    let aotAvailable: Bool
    let naxAvailable: Bool
    let armed: Bool
    let exactGeometryExpected: Bool
    let attempts: UInt64
    let hits: UInt64
    let effective: Bool
    let fallbackNAX: UInt64
    let fallbackOuterRoute: UInt64
    let fallbackQuantization: UInt64
    let fallbackTopology: UInt64
    let fallbackAssignmentCount: UInt64
    let fallbackGeometry: UInt64
    let fallbackMetallibUnavailable: UInt64
    let fallbacks: UInt64

    init(
        diagnostics: GPU.Gemma4ExpertQMMDiagnostics,
        exactGeometryExpected: Bool
    ) {
        requested = diagnostics.requested
        aotAvailable = diagnostics.aotAvailable
        naxAvailable = diagnostics.naxAvailable
        armed = diagnostics.armed
        self.exactGeometryExpected = exactGeometryExpected
        attempts = diagnostics.attempts
        hits = diagnostics.hits
        effective = diagnostics.hits > 0
        fallbackNAX = diagnostics.fallbackNAX
        fallbackOuterRoute = diagnostics.fallbackOuterRoute
        fallbackQuantization = diagnostics.fallbackQuantization
        fallbackTopology = diagnostics.fallbackTopology
        fallbackAssignmentCount = diagnostics.fallbackAssignmentCount
        fallbackGeometry = diagnostics.fallbackGeometry
        fallbackMetallibUnavailable = diagnostics.fallbackMetallibUnavailable
        fallbacks = diagnostics.fallbacks
    }

    init(
        requested: Bool, aotAvailable: Bool, naxAvailable: Bool,
        armed: Bool = true,
        exactGeometryExpected: Bool, attempts: UInt64, hits: UInt64,
        fallbackNAX: UInt64 = 0, fallbackOuterRoute: UInt64 = 0,
        fallbackQuantization: UInt64 = 0, fallbackTopology: UInt64 = 0,
        fallbackAssignmentCount: UInt64 = 0, fallbackGeometry: UInt64 = 0,
        fallbackMetallibUnavailable: UInt64 = 0
    ) {
        self.requested = requested
        self.aotAvailable = aotAvailable
        self.naxAvailable = naxAvailable
        self.armed = armed
        self.exactGeometryExpected = exactGeometryExpected
        self.attempts = attempts
        self.hits = hits
        self.effective = hits > 0
        self.fallbackNAX = fallbackNAX
        self.fallbackOuterRoute = fallbackOuterRoute
        self.fallbackQuantization = fallbackQuantization
        self.fallbackTopology = fallbackTopology
        self.fallbackAssignmentCount = fallbackAssignmentCount
        self.fallbackGeometry = fallbackGeometry
        self.fallbackMetallibUnavailable = fallbackMetallibUnavailable
        self.fallbacks =
            fallbackNAX + fallbackOuterRoute + fallbackQuantization
            + fallbackTopology + fallbackAssignmentCount + fallbackGeometry
            + fallbackMetallibUnavailable
    }


    var guardFailure: String? {
        guard armed else {
            return "safe R1 diagnostics were not armed for the measured cell"
        }
        guard attempts == hits + fallbacks else {
            return "safe R1 counters are inconsistent: attempts=\(attempts), "
                + "hits+fallbacks=\(hits + fallbacks)"
        }
        guard requested else {
            return attempts == 0
                ? nil : "safe R1 recorded \(attempts) attempts while not requested"
        }
        guard exactGeometryExpected else { return nil }
        if naxAvailable {
            return fallbackNAX > 0
                ? nil : "safe R1 expected NAX precedence but recorded no NAX fallback"
        }
        return hits > 0
            ? nil : "safe R1 was requested for exact non-NAX geometry but recorded no hit"
    }
}

struct CellOptimizationProvenance: Codable, Sendable, Equatable {
    let model: ModelOptimizationProvenance
    let layer18IntermediateSubmissions: Int
    let layer18ExpectedMinimumSubmissions: Int
    let layer18Engaged: Bool
    let weightedUnsortEffectiveCalls: Int
    let weightedUnsortEngaged: Bool
    let safeR1: SafeR1Provenance

    init(
        model: ModelOptimizationProvenance,
        layer18IntermediateSubmissions: Int,
        layer18ExpectedMinimumSubmissions: Int,
        weightedUnsortEffectiveCalls: Int,
        safeR1: SafeR1Provenance
    ) {
        self.model = model
        self.layer18IntermediateSubmissions = layer18IntermediateSubmissions
        self.layer18ExpectedMinimumSubmissions = layer18ExpectedMinimumSubmissions
        self.layer18Engaged = layer18IntermediateSubmissions > 0
        self.weightedUnsortEffectiveCalls = weightedUnsortEffectiveCalls
        self.weightedUnsortEngaged = weightedUnsortEffectiveCalls > 0
        self.safeR1 = safeR1
    }

    var guardFailure: String? {
        if model.layer18Effective
            && layer18IntermediateSubmissions < layer18ExpectedMinimumSubmissions
        {
            return "layer18 expected at least \(layer18ExpectedMinimumSubmissions) "
                + "intermediate submissions but recorded \(layer18IntermediateSubmissions)"
        }
        if model.weightedUnsortEffective && !weightedUnsortEngaged {
            return "weighted expert unsort was effective but recorded no call"
        }
        return safeR1.guardFailure
    }

    func markdown(scope: String) -> String {
        "- optimization provenance [\(scope)]: \(model.markdown); "
            + "layer18ExpectedMinimumSubmissions=\(layer18ExpectedMinimumSubmissions), "
            + "layer18Submissions=\(layer18IntermediateSubmissions), "
            + "layer18Engaged=\(layer18Engaged); "
            + "weightedCalls=\(weightedUnsortEffectiveCalls), "
            + "weightedEngaged=\(weightedUnsortEngaged); "
            + "safeR1(requested=\(safeR1.requested), "
            + "effective=\(safeR1.effective), armed=\(safeR1.armed), "
            + "aot=\(safeR1.aotAvailable), nax=\(safeR1.naxAvailable), "
            + "exactGeometryExpected=\(safeR1.exactGeometryExpected), "
            + "attempts=\(safeR1.attempts), hits=\(safeR1.hits), "
            + "fallbacks=\(safeR1.fallbacks), "
            + "fallbackNAX=\(safeR1.fallbackNAX), "
            + "fallbackOuterRoute=\(safeR1.fallbackOuterRoute), "
            + "fallbackQuantization=\(safeR1.fallbackQuantization), "
            + "fallbackTopology=\(safeR1.fallbackTopology), "
            + "fallbackAssignmentCount=\(safeR1.fallbackAssignmentCount), "
            + "fallbackGeometry=\(safeR1.fallbackGeometry), "
            + "fallbackMetallibUnavailable=\(safeR1.fallbackMetallibUnavailable))"
    }
}

private struct SafeR1PrefillGroupKey: Hashable {
    let width: Int
    let samples: Bool
}

/// Whether the first scheduled prefill wave has one of the three exact token
/// counts accepted by safe R1 (the kernel sees token count × Gemma topK=8
/// assignments). CBv2 coalesces rows only when both chunk width and whether
/// the chunk samples are equal, so the guard mirrors those group keys.
func safeR1ExactGeometryExpected(
    modelEligible: Bool,
    promptLengths: [Int],
    prefillChunkSize: Int
) -> Bool {
    guard modelEligible, prefillChunkSize > 0 else { return false }
    let rows = promptLengths.map {
        SafeR1PrefillGroupKey(
            width: min($0, prefillChunkSize),
            samples: $0 <= prefillChunkSize)
    }
    let groups = Dictionary(grouping: rows, by: { $0 })
    return groups.contains { key, rows in
        let tokenCount = key.width * rows.count
        return tokenCount == 512 || tokenCount == 1024 || tokenCount == 2048
    }
}

func benchmarkJSONString<T: Encodable>(_ value: T) throws -> String {
    let encoder = JSONEncoder()
    encoder.outputFormatting = [.sortedKeys]
    return String(decoding: try encoder.encode(value), as: UTF8.self)
}

struct CellResult: Codable, Sendable {
    var engine: String
    var batch: Int
    var promptMix: [Int]
    var decodeTPSPerRequest: Double
    var aggregateTPS: Double
    var ttftP50Ms: Double
    var itlP50Ms: Double
    var perRequest: [String]
    var optimizationProvenance: CellOptimizationProvenance?

    var markdownRow: String {
        String(
            format: "| %@ | %d | %@ | %.1f | %.1f | %.0f | %.1f |",
            engine, batch, promptMix.map(String.init).joined(separator: "/"),
            decodeTPSPerRequest, aggregateTPS, ttftP50Ms, itlP50Ms)
    }

    static let markdownHeader = """
        | engine | B | prompts (tok) | decode TPS/req | agg TPS | TTFT p50 (ms) | ITL p50 (ms) |
        |---|---|---|---|---|---|---|
        """
}

/// Validate and serialize one cell's fail-closed optimization provenance.
func optimizationProvenanceLines(
    _ cell: CellResult, scope: String
) throws -> [String] {
    guard let provenance = cell.optimizationProvenance else {
        throw CBv2KVError.backendIneligible(
            reason: "optimization provenance was not armed for \(scope)")
    }
    if let failure = provenance.guardFailure {
        throw CBv2KVError.backendIneligible(
            reason: "invalid optimization provenance in \(scope): \(failure)")
    }
    return [
        provenance.markdown(scope: scope),
        "- optimization-cell-json [\(scope)]: \(try benchmarkJSONString(cell))",
    ]
}

/// Keep every Markdown table row contiguous, then append the per-cell
/// provenance records in the same order as their rows.
func performanceMarkdown(
    rows: [String], provenanceLines: [String]
) -> String {
    var lines = [CellResult.markdownHeader]
    lines.append(contentsOf: rows)
    if !provenanceLines.isEmpty {
        lines.append("")
        lines.append(contentsOf: provenanceLines)
    }
    return lines.joined(separator: "\n")
}

func summarize(
    engine: String,
    batch: Int,
    promptMix: [Int],
    results: [RunResult],
    optimizationProvenance: CellOptimizationProvenance? = nil
) -> CellResult {
    let totalTokens = results.reduce(0) { $0 + $1.tokens.count }
    let start = results.map(\.submittedAt).min() ?? 0
    let end = results.map(\.finishedAt).max() ?? 1
    let ttfts = results.map(\.ttftMs).sorted()
    let itls = results.flatMap(\.itlsMs).sorted()
    let decodeTPS = results.map(\.decodeTPS)
    let perRequest = results.enumerated().map { i, r in
        String(
            format: "    req %d: prompt=%d tokens=%d ttft=%.0fms decodeTPS=%.1f finish=%@",
            i, r.promptTokens, r.tokens.count, r.ttftMs, r.decodeTPS, r.finish)
    }
    return CellResult(
        engine: engine, batch: batch, promptMix: promptMix,
        decodeTPSPerRequest: decodeTPS.reduce(0, +) / Double(max(1, decodeTPS.count)),
        aggregateTPS: Double(totalTokens) / max(end - start, 1e-9),
        ttftP50Ms: percentile(ttfts, 0.5),
        itlP50Ms: percentile(itls, 0.5),
        perRequest: perRequest,
        optimizationProvenance: optimizationProvenance)
}

/// Prompt-length mix for one perf cell. The default mixes are the historical
/// hardcoded ones — unchanged so existing reports stay reproducible.
/// `lengths` (from `--prompt-lengths`) replaces them and is cycled to exactly
/// `batch` entries, keeping the batch axis (concurrency) independent of the
/// length axis.
func promptMix(batch: Int, lengths: [Int] = []) -> [Int] {
    guard !lengths.isEmpty else {
        switch batch {
        case 1: return [500]
        case 2: return [100, 1500]
        case 4: return [100, 500, 1500, 500]
        default: return Array(repeating: 500, count: batch)
        }
    }
    guard batch > 0 else { return [] }
    return (0 ..< batch).map { lengths[$0 % lengths.count] }
}

func runV2Cell(
    context: ModelContext, hooks: V2ModelHooks, backend: V2Backend,
    batch: Int, promptLengths: [Int], steps: Int, vocabSize: Int, kvBytes: Int,
    trackOptimizationProvenance: Bool = false
) async throws -> CellResult {
    let prefillChunkSize = 512
    let engine = try makeV2Engine(
        context: context, hooks: hooks, backend: backend,
        schedulerConfig: CBv2SchedulerConfig(
            maxConcurrentRequests: batch, maxBatchedTokensPerStep: 2048,
            prefillChunkSize: prefillChunkSize, maxWaiting: 16),
        kvBytes: kvBytes)

    // One shared measured boundary after all warmup. Performance cells arm
    // only the independent provenance counters; phase timers remain in their
    // caller-selected state. Every counter snapshots/disarms after shutdown.
    // Measurement boundary: reset the process-wide peak AFTER engine
    // construction so the caller's per-row gpuPeak covers only the measured
    // request group — not an earlier cell's high-water mark.
    MLX.Memory.peakMemory = 0
    if trackOptimizationProvenance {
        resetWeightedExpertUnsortStats()
        MLX.GPU.clearAndArmGemma4ExpertQMMDiagnostics()
        CBv2StepProfiler.armEvents()
    }
    let results = await withTaskGroup(of: (Int, RunResult).self) { group in
        for (i, length) in promptLengths.enumerated() {
            let prompt = syntheticPrompt(
                length: length, seed: 0xFACE &+ UInt64(i), vocabSize: vocabSize)
            group.addTask { @Sendable in
                let r = try? await runV2Request(
                    engine: engine, id: UInt64(1000 + i), promptTokens: prompt,
                    maxTokens: steps, stopTokens: [])
                return (i, r ?? RunResult())
            }
        }
        var all: [(Int, RunResult)] = []
        for await entry in group { all.append(entry) }
        return all.sorted { $0.0 < $1.0 }.map(\.1)
    }
    await engine.shutdown()

    let optimizationProvenance: CellOptimizationProvenance?
    if trackOptimizationProvenance {
        let layer18Submissions = CBv2StepProfiler.snapshotAndDisarmEvents()[
            "v2.gemma4.prefill.chunk_eval"] ?? 0
        let weighted = weightedExpertUnsortProvenance(
            requested: hooks.optimizations.weightedUnsortEffective)
        let r1 = SafeR1Provenance(
            diagnostics: MLX.GPU.snapshotAndDisarmGemma4ExpertQMMDiagnostics(),
            exactGeometryExpected: safeR1ExactGeometryExpected(
                modelEligible: hooks.optimizations.safeR1GeometryEligible,
                promptLengths: promptLengths,
                prefillChunkSize: prefillChunkSize))
        let expectedLayer18Minimum: Int
        if let interval = hooks.optimizations.layer18Interval,
            interval > 0,
            promptLengths.contains(where: { $0 > 1 })
        {
            expectedLayer18Minimum = hooks.layerKinds.count / interval
        } else {
            expectedLayer18Minimum = 0
        }
        optimizationProvenance = CellOptimizationProvenance(
            model: hooks.optimizations,
            layer18IntermediateSubmissions: layer18Submissions,
            layer18ExpectedMinimumSubmissions: expectedLayer18Minimum,
            weightedUnsortEffectiveCalls: weighted.effectiveCalls,
            safeR1: r1)
    } else {
        optimizationProvenance = nil
    }

    return summarize(
        engine: backend.rawValue,
        batch: batch, promptMix: promptLengths, results: results,
        optimizationProvenance: optimizationProvenance)
}

// MARK: - Correctness

struct CorrectnessOutcome: Sendable {
    var name: String
    var pass: Bool
    var detail: String
}

func firstDivergence(_ a: [Int], _ b: [Int]) -> Int? {
    for i in 0 ..< min(a.count, b.count) where a[i] != b[i] { return i }
    return a.count == b.count ? nil : min(a.count, b.count)
}

/// Repetition-loop heuristic: does any 8-gram appear ≥ 4 times in the tail?
func hasRepetitionLoop(_ tokens: [Int]) -> Bool {
    guard tokens.count >= 32 else { return false }
    let tail = Array(tokens.suffix(96))
    var counts: [ArraySlice<Int>: Int] = [:]
    for i in 0 ... (tail.count - 8) {
        counts[tail[i ..< (i + 8)], default: 0] += 1
    }
    return counts.values.max() ?? 0 >= 4
}

func runCorrectness(
    context: ModelContext, hooks: V2ModelHooks, kvBytes: Int,
    chatTokens: (String) -> [Int], log: (String) -> Void
) async -> [CorrectnessOutcome] {
    var outcomes: [CorrectnessOutcome] = []
    let eos = context.configuration.eosTokenIds
    let defaultConfig = CBv2SchedulerConfig(
        maxConcurrentRequests: 4, maxBatchedTokensPerStep: 2048, prefillChunkSize: 512,
        maxWaiting: 16)

    func freshEngine(_ config: CBv2SchedulerConfig? = nil) throws -> EngineV2 {
        try makeV2Engine(
            context: context, hooks: hooks, backend: .contiguous,
            schedulerConfig: config ?? defaultConfig, kvBytes: kvBytes)
    }

    let target = chatTokens("Explain why the sky is blue in two sentences.")
    let shortNeighbor = chatTokens("List three prime numbers.")
    let longText = String(
        repeating: "The quick brown fox jumps over the lazy dog while the seasoned cartographer "
            + "annotates ancient maps with meticulous margin notes about tides, trade winds, "
            + "and the slow drift of continents across geological epochs. ",
        count: 40)
    let longNeighbor = chatTokens(
        "Summarize the following passage in one sentence: " + longText)
    log(
        "prompt tokens: target=\(target.count) short=\(shortNeighbor.count) "
            + "long=\(longNeighbor.count) eos=\(eos.sorted())")

    // 1a. B=1 sanity ------------------------------------------------------
    do {
        let engine = try freshEngine()
        let r = try await runV2Request(
            engine: engine, id: 1, promptTokens: target, maxTokens: 200, stopTokens: eos)
        await engine.shutdown()
        let stopped = r.finish == "stop"
        let looped = hasRepetitionLoop(r.tokens)
        let pass = stopped && !looped && !r.text.isEmpty
        log("[b1-sanity] finish=\(r.finish) tokens=\(r.tokens.count) loop=\(looped)")
        log("[b1-sanity] text: \(r.text)")
        outcomes.append(
            CorrectnessOutcome(
                name: "b1-sanity", pass: pass,
                detail:
                    "finish=\(r.finish) completion=\(r.tokens.count) repetitionLoop=\(looped)"))
    } catch {
        outcomes.append(
            CorrectnessOutcome(name: "b1-sanity", pass: false, detail: "error: \(error)"))
    }

    // 1b. Batch-composition invariance ------------------------------------
    var soloTokens: [Int] = []
    do {
        // (i) solo — run twice on fresh engines: same-composition
        // determinism is the precondition for any invariance claim.
        let engine = try freshEngine()
        let solo = try await runV2Request(
            engine: engine, id: 10, promptTokens: target, maxTokens: 64, stopTokens: eos,
            topLogprobs: 4)
        await engine.shutdown()
        let engine2 = try freshEngine()
        let solo2 = try await runV2Request(
            engine: engine2, id: 11, promptTokens: target, maxTokens: 64, stopTokens: eos,
            topLogprobs: 4)
        await engine2.shutdown()
        soloTokens = solo.tokens
        let soloRepeatDiv = firstDivergence(solo.tokens, solo2.tokens)
        log("[invariance] solo tokens=\(solo.tokens.count) finish=\(solo.finish)")
        log("[invariance] solo-repeat divergence=\(String(describing: soloRepeatDiv))")
        log("[invariance] solo text: \(solo.text)")

        // (ii) B=3 burst with short + long neighbors
        let burstEngine = try freshEngine()
        let burst = try await withThrowingTaskGroup(of: (Int, RunResult).self) { group in
            let submissions: [(Int, [Int], Int)] = [
                (0, shortNeighbor, 96), (1, longNeighbor, 96), (2, target, 64),
            ]
            for (i, prompt, budget) in submissions {
                group.addTask { @Sendable in
                    (
                        i,
                        try await runV2Request(
                            engine: burstEngine, id: UInt64(20 + i), promptTokens: prompt,
                            maxTokens: budget, stopTokens: eos, topLogprobs: 4)
                    )
                }
            }
            var all: [(Int, RunResult)] = []
            for try await entry in group { all.append(entry) }
            return all.sorted { $0.0 < $1.0 }.map(\.1)
        }
        await burstEngine.shutdown()
        let burstTarget = burst[2]
        let burstDiv = firstDivergence(soloTokens, burstTarget.tokens)
        log("[invariance] burst target tokens=\(burstTarget.tokens.count) divergence=\(String(describing: burstDiv))")
        if let d = burstDiv {
            log("[invariance] " + logprobDetail(solo, at: d, label: "solo @\(d)"))
            log("[invariance] " + logprobDetail(burstTarget, at: d, label: "burst @\(d)"))
        }

        // (iii) join mid-stream: neighbors decoding first, then the target.
        let joinEngine = try freshEngine()
        let c1 = TokenCounter()
        let c2 = TokenCounter()
        let n1Submitted = CFAbsoluteTimeGetCurrent()
        let n1Stream = try joinEngine.submit(
            CBv2Request(
                id: CBv2RequestID(30), promptTokens: shortNeighbor,
                sampling: CBv2SamplingParams(temperature: 0), maxTokens: 192, stopTokens: []))
        let n2Stream = try joinEngine.submit(
            CBv2Request(
                id: CBv2RequestID(31), promptTokens: longNeighbor,
                sampling: CBv2SamplingParams(temperature: 0), maxTokens: 192, stopTokens: []))
        let n1Task = Task { await collectV2(n1Stream, submittedAt: n1Submitted, counter: c1) }
        let n2Task = Task { await collectV2(n2Stream, submittedAt: n1Submitted, counter: c2) }
        let waitStart = CFAbsoluteTimeGetCurrent()
        while true {
            let (n1, n2) = await (c1.count, c2.count)
            if n1 >= 5 && n2 >= 5 { break }
            if CFAbsoluteTimeGetCurrent() - waitStart > 120 { break }
            try await Task.sleep(nanoseconds: 5_000_000)
        }
        let midStarted = await (c1.count, c2.count)
        let join = try await runV2Request(
            engine: joinEngine, id: 32, promptTokens: target, maxTokens: 64, stopTokens: eos,
            topLogprobs: 4)
        joinEngine.cancel(CBv2RequestID(30))
        joinEngine.cancel(CBv2RequestID(31))
        _ = await n1Task.value
        _ = await n2Task.value
        await joinEngine.shutdown()
        let joinDiv = firstDivergence(soloTokens, join.tokens)
        log(
            "[invariance] mid-join: neighbors had \(midStarted) tokens at join; "
                + "target tokens=\(join.tokens.count) divergence=\(String(describing: joinDiv))")
        if let d = joinDiv {
            log("[invariance] " + logprobDetail(solo, at: d, label: "solo @\(d)"))
            log("[invariance] " + logprobDetail(join, at: d, label: "join @\(d)"))
        }

        // Neighbor-content invariance at fixed B: burst and mid-join both
        // decode the target as one row of a 3-row batch but with DIFFERENT
        // neighbor progress/content. Token-equality here is the engine's
        // cross-request isolation guarantee; solo-vs-batched inequality is
        // batch-size GEMM numerics (kernel config keyed on B), not bleed.
        let neighborDiv = firstDivergence(burstTarget.tokens, join.tokens)
        log(
            "[invariance] neighbor-invariance (burst vs mid-join at B=3): "
                + "divergence=\(String(describing: neighborDiv))")

        let pass =
            soloRepeatDiv == nil && burstDiv == nil && joinDiv == nil && !soloTokens.isEmpty
        var detail = "solo=\(soloTokens.count) tok"
        detail +=
            soloRepeatDiv == nil
            ? "; solo-repeat deterministic"
            : "; SOLO-REPEAT NONDETERMINISTIC at index \(soloRepeatDiv!)"
        detail +=
            neighborDiv == nil
            ? "; neighbor-invariant at B=3 (burst == mid-join)"
            : "; NEIGHBOR-DEPENDENT at B=3, index \(neighborDiv!)"
        if let d = burstDiv {
            detail +=
                "; BURST DIVERGES from solo at index \(d) (solo=\(soloTokens[safe: d] ?? -1) "
                + "burst=\(burstTarget.tokens[safe: d] ?? -1))"
        } else {
            detail += "; burst identical to solo"
        }
        if let d = joinDiv {
            detail +=
                "; MID-JOIN DIVERGES from solo at index \(d) (solo=\(soloTokens[safe: d] ?? -1) "
                + "join=\(join.tokens[safe: d] ?? -1))"
        } else {
            detail += "; mid-join identical to solo"
        }
        outcomes.append(CorrectnessOutcome(name: "invariance", pass: pass, detail: detail))
    } catch {
        outcomes.append(
            CorrectnessOutcome(name: "invariance", pass: false, detail: "error: \(error)"))
    }

    // 1c. Chunked-prefill invariance ---------------------------------------
    do {
        let longPrompt = longNeighbor
        let chunkedEngine = try freshEngine()  // prefillChunkSize 512
        let chunked = try await runV2Request(
            engine: chunkedEngine, id: 40, promptTokens: longPrompt, maxTokens: 64,
            stopTokens: eos, topLogprobs: 4)
        await chunkedEngine.shutdown()

        let unchunkedEngine = try freshEngine(
            CBv2SchedulerConfig(
                maxConcurrentRequests: 4, maxBatchedTokensPerStep: 8192,
                prefillChunkSize: 8192, maxWaiting: 16))
        let unchunked = try await runV2Request(
            engine: unchunkedEngine, id: 41, promptTokens: longPrompt, maxTokens: 64,
            stopTokens: eos, topLogprobs: 4)
        await unchunkedEngine.shutdown()

        let div = firstDivergence(chunked.tokens, unchunked.tokens)
        log(
            "[chunked-prefill] chunked=\(chunked.tokens.count) tok "
                + "unchunked=\(unchunked.tokens.count) tok divergence=\(String(describing: div))")
        if let d = div {
            log("[chunked-prefill] " + logprobDetail(chunked, at: d, label: "chunked @\(d)"))
            log("[chunked-prefill] " + logprobDetail(unchunked, at: d, label: "unchunked @\(d)"))
        }
        log("[chunked-prefill] chunked text: \(chunked.text)")
        let detail: String
        if let d = div {
            detail =
                "DIVERGES at index \(d) (chunked=\(chunked.tokens[safe: d] ?? -1) "
                + "unchunked=\(unchunked.tokens[safe: d] ?? -1)); "
                + "prompt=\(longPrompt.count) tok"
        } else {
            detail = "token-exact over \(chunked.tokens.count) tokens (prompt=\(longPrompt.count))"
        }
        outcomes.append(
            CorrectnessOutcome(name: "chunked-prefill", pass: div == nil, detail: detail))
    } catch {
        outcomes.append(
            CorrectnessOutcome(name: "chunked-prefill", pass: false, detail: "error: \(error)"))
    }

    return outcomes
}

extension Array {
    subscript(safe index: Int) -> Element? {
        indices.contains(index) ? self[index] : nil
    }
}

// MARK: - Entry point

func sysctlString(_ name: String) -> String {
    var size = 0
    sysctlbyname(name, nil, &size, nil, 0)
    guard size > 0 else { return "unknown" }
    var buffer = [UInt8](repeating: 0, count: size)
    sysctlbyname(name, &buffer, &size, nil, 0)
    return String(decoding: buffer.prefix(while: { $0 != 0 }), as: UTF8.self)
}

/// Revision of the mlx-swift-lm checkout this report describes.
///
/// This *must* be the revision the executable was compiled from, not the
/// revision the checkout happens to be sitting on when the report is written.
/// The two diverge constantly: `.build/release/BenchCBv2` survives a
/// `git checkout`, and a long benchmark outlives whatever the tree did while
/// it ran. A `git rev-parse HEAD` at report time therefore attributes numbers
/// to code that did not produce them — the one failure mode provenance exists
/// to prevent.
///
/// `BenchBuildRevision.value` is generated by `Plugins/BenchRevisionStamp`
/// (a SwiftPM prebuild command running `scripts/stamp-bench-revision.sh`) and
/// compiled into this binary, so it is fixed at the moment the binary is
/// produced. There is deliberately no runtime git fallback: a stale-but-real
/// SHA is worse than `unknown`.
func buildRevision() -> String {
    BenchBuildRevision.value
}

/// 1-minute load average — stamped into the report header so a benchmark
/// taken on a contended host is visibly suspect. A busy host (parallel
/// swift build, a serving provider) halves eager decode TPS and skews
/// engine comparisons; that is exactly how the first GPT-OSS report came
/// to show v2 26 TPS vs legacy 35 when a clean host shows 107 vs 79.
func loadAverage1m() -> Double {
    var loads = [Double](repeating: 0, count: 3)
    guard getloadavg(&loads, 3) >= 1 else { return -1 }
    return loads[0]
}

/// Contention sentinel for the report header: 1m load average plus whether
/// any darkbloom provider process is alive (the usual GPU/CPU competitor on
/// dev machines).
func hostContentionSummary() -> (line: String, contended: Bool) {
    let load = loadAverage1m()
    let cores = ProcessInfo.processInfo.processorCount
    let task = Process()
    task.executableURL = URL(fileURLWithPath: "/usr/bin/pgrep")
    // -x (exact process name): -f would false-positive on any shell whose
    // command line merely contains "DARKBLOOM_COMPILED_DECODE=…" — including
    // the one that launched this benchmark.
    task.arguments = ["-x", "darkbloom"]
    let pipe = Pipe()
    task.standardOutput = pipe
    task.standardError = Pipe()
    var darkbloom = ""
    if (try? task.run()) != nil {
        let data = pipe.fileHandleForReading.readDataToEndOfFile()
        task.waitUntilExit()
        darkbloom = String(decoding: data, as: UTF8.self)
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }
    let contended = load > Double(cores) / 2 || !darkbloom.isEmpty
    var line = String(format: "load avg (1m) %.1f / %d cores", load, cores)
    line += darkbloom.isEmpty ? "; no darkbloom process" : "; DARKBLOOM RUNNING"
    if contended { line += " — **HOST CONTENDED, numbers suspect**" }
    return (line, contended)
}

// MARK: - Invocation provenance

/// Characters that survive an unquoted POSIX shell word untouched.
private let shellSafeCharacters = Set(
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_@%+=:,./-")

/// POSIX-shell quoting for one argv element.
///
/// The report claims to record the exact invocation. Joining argv with a
/// single space breaks that claim the moment an element contains whitespace:
/// `--label "paged vs contiguous"` reads back as three arguments, and a model
/// path with a space is unreconstructable. Single-quoting (with `'` written as
/// `'\''`) is lossless for every possible byte string, so pasting the recorded
/// line into a shell reproduces the original argv exactly.
func shellQuote(_ argument: String) -> String {
    guard !argument.isEmpty else { return "''" }
    if argument.allSatisfy({ shellSafeCharacters.contains($0) }) { return argument }
    return "'" + argument.replacingOccurrences(of: "'", with: "'\\''") + "'"
}

func shellQuotedInvocation(_ arguments: [String]) -> String {
    arguments.map(shellQuote).joined(separator: " ")
}

// MARK: - Options

enum BenchOptionError: Error, Equatable, CustomStringConvertible {
    case missingValue(option: String)
    case invalidValue(option: String, value: String, requirement: String)
    case unknownOption(String)
    case missingModel

    var description: String {
        switch self {
        case .missingValue(let option):
            return "\(option) requires a value"
        case .invalidValue(let option, let value, let requirement):
            return "\(option): invalid value \(shellQuote(value)) — \(requirement)"
        case .unknownOption(let option):
            return "unknown option \(shellQuote(option))"
        case .missingModel:
            return "--model is required"
        }
    }
}

/// Strict positive-integer parse.
///
/// The permissive `Int($0)` + `filter { $0 > 0 }` this replaces *dropped*
/// unparseable elements, so `--prompt-lengths 100O0` (letter O) yielded an
/// empty list and the benchmark silently ran the default 500/1500 mix under a
/// report header that still claimed the requested axis. A benchmark that
/// quietly measures a different experiment than the one requested is worse
/// than one that refuses to start.
func parsePositiveInt(_ raw: String, option: String) throws -> Int {
    guard let value = Int(raw), value > 0 else {
        throw BenchOptionError.invalidValue(
            option: option, value: raw, requirement: "expected a positive integer")
    }
    return value
}

/// Comma-separated positive integers. Every element must be valid; an empty
/// element (or an empty list) is an error rather than a silent omission.
func parsePositiveIntList(_ raw: String, option: String) throws -> [Int] {
    let elements = raw
        .split(separator: ",", omittingEmptySubsequences: false)
        .map { $0.trimmingCharacters(in: .whitespaces) }
    return try elements.map { try parsePositiveInt($0, option: option) }
}

/// Parsed command line. Kept separate from `main` so the parse is testable
/// without a model on disk.
struct BenchOptions: Equatable {
    var modelPath = ""
    var mode = "all"
    var engines = ["v2", "v2-paged"]
    var batches = [1, 2, 4]
    var steps = 128
    var label = ""
    var outPath: String?
    var kvBytes = 16 << 30
    var promptLengths: [Int] = []
    var maxSeqLen: Int?
    /// `--print-revision`: print the build stamp and exit, without a model.
    var printRevisionOnly = false

    static let modes: Set<String> = ["all", "correctness", "perf", "profile"]

    static let usage = """
        usage: BenchCBv2 --model <dir> [--mode all|correctness|perf|profile]
               [--engines v2,v2-paged] [--batches 1,2,4]
               [--steps N] [--label tag] [--kv-gb N] [--out report.md]
               [--prompt-lengths 500,10000] [--max-seq-len N]
               [--print-revision]
        """

    /// `arguments` excludes argv[0].
    static func parse(_ arguments: [String]) throws -> BenchOptions {
        var options = BenchOptions()
        var pending = arguments[...]
        func value(for option: String) throws -> String {
            guard let next = pending.popFirst() else {
                throw BenchOptionError.missingValue(option: option)
            }
            return next
        }
        while let argument = pending.popFirst() {
            switch argument {
            case "--model": options.modelPath = try value(for: argument)
            case "--mode":
                let mode = try value(for: argument)
                guard modes.contains(mode) else {
                    throw BenchOptionError.invalidValue(
                        option: argument, value: mode,
                        requirement: "expected one of "
                            + modes.sorted().joined(separator: "|"))
                }
                options.mode = mode
            case "--engines":
                let raw = try value(for: argument)
                let names = raw
                    .split(separator: ",", omittingEmptySubsequences: false)
                    .map { $0.trimmingCharacters(in: .whitespaces) }
                guard names.allSatisfy({ !$0.isEmpty }) else {
                    throw BenchOptionError.invalidValue(
                        option: argument, value: raw,
                        requirement: "expected comma-separated engine names")
                }
                options.engines = names
            case "--batches":
                options.batches = try parsePositiveIntList(
                    try value(for: argument), option: argument)
            case "--prompt-lengths":
                options.promptLengths = try parsePositiveIntList(
                    try value(for: argument), option: argument)
            case "--max-seq-len":
                options.maxSeqLen = try parsePositiveInt(
                    try value(for: argument), option: argument)
            case "--steps":
                options.steps = try parsePositiveInt(
                    try value(for: argument), option: argument)
            case "--kv-gb":
                options.kvBytes = try parsePositiveInt(
                    try value(for: argument), option: argument) << 30
            case "--label": options.label = try value(for: argument)
            case "--out": options.outPath = try value(for: argument)
            case "--print-revision": options.printRevisionOnly = true
            default:
                throw BenchOptionError.unknownOption(argument)
            }
        }
        guard options.printRevisionOnly || !options.modelPath.isEmpty else {
            throw BenchOptionError.missingModel
        }
        return options
    }

    /// Longest prompt any cell will submit, across the batch axis.
    var longestPrompt: Int {
        batches.map { promptMix(batch: $0, lengths: promptLengths).max() ?? 0 }.max() ?? 0
    }

    /// Paged pool sizing: `nominalMaxSequenceLength` splits pool capacity
    /// across layer groups by per-sequence demand, so a 10k prompt against a
    /// 4096 nominal starves the full-attention group. Derived from the longest
    /// cell (prompt + generated tokens), never below the historical 4096, so a
    /// run with no new flags sizes the pool exactly as before.
    var pagedNominalMaxSequenceLength: Int {
        maxSeqLen ?? max(4096, longestPrompt + steps)
    }

    var promptAxisDescription: String {
        promptLengths.isEmpty
            ? "default mix (B=1 500; B=2 100,1500; B=4 100,500,1500,500; else 500 x B)"
            : promptLengths.map(String.init).joined(separator: ",")
    }
}

// MARK: - Report header

/// Provenance block prepended to the report. Pure, so the recorded invocation
/// and revision can be tested without running a benchmark.
func reportHeader(
    options: BenchOptions, argv: [String], chip: String, ramGB: UInt64,
    osVersion: String, hostLine: String, revision: String, date: Date
) -> String {
    func row(_ name: String, _ value: String) -> String {
        "| \(name) | \(markdownCellEscaped(value)) |"
    }
    var rows = [row("Model", options.modelPath)]
    if !options.label.isEmpty { rows.append(row("Label", options.label)) }
    rows += [
        row("Chip", chip),
        row("RAM", "\(ramGB) GB"),
        row("OS", osVersion),
        row("Host at start", hostLine),
        row("Invocation", "`\(shellQuotedInvocation(argv))`"),
        row("Prompt lengths", options.promptAxisDescription),
        row("Paged nominalMaxSeqLen", "\(options.pagedNominalMaxSequenceLength)"),
        // The revision the *binary* was built from — see `buildRevision()`.
        row("mlx-swift-lm (build)", revision),
        row("Date", ISO8601DateFormatter().string(from: date)),
    ]
    return """
        # BenchCBv2RealModel report

        | | |
        |---|---|
        \(rows.joined(separator: "\n"))


        """
}

/// Program body for the `BenchCBv2` executable.
///
/// Lives in the library so the harness-integrity tests can reach it (and its
/// neighbours) without putting an executable in the test target's dependency
/// graph — see the file header. The executable's `@main` does nothing but
/// `await BenchCBv2Driver.run()`, so the CLI surface is defined here.
public enum BenchCBv2Driver {
    public static func run() async {
        // Unbuffered stdout: a Metal trap must not eat buffered results.
        setvbuf(stdout, nil, _IONBF, 0)

        let argv = CommandLine.arguments
        let options: BenchOptions
        do {
            options = try BenchOptions.parse(Array(argv.dropFirst()))
        } catch let error as BenchOptionError {
            print("error: \(error)")
            print(BenchOptions.usage)
            exit(64)
        } catch {
            print("error: \(error)")
            exit(64)
        }

        if options.printRevisionOnly {
            print(buildRevision())
            exit(0)
        }

        let directory = URL(fileURLWithPath: options.modelPath)
        guard FileManager.default.fileExists(atPath: directory.path) else {
            print("error: model directory does not exist: \(directory.path)")
            exit(66)
        }

        benchPagedNominalMaxSequenceLength = options.pagedNominalMaxSequenceLength

        let contention = hostContentionSummary()
        print("== BenchCBv2RealModel ==")
        print("model: \(options.modelPath)")
        print("mode: \(options.mode)  engines: \(options.engines)"
            + "  batches: \(options.batches)  steps: \(options.steps)")
        print("prompt lengths: "
            + (options.promptLengths.isEmpty ? "default mix" : options.promptLengths.description)
            + "  paged nominalMaxSeqLen: \(benchPagedNominalMaxSequenceLength)")
        print("host: \(contention.line)")
        if contention.contended {
            print("WARNING: host is contended — eager decode is CPU-bound, results will be skewed")
        }

        do {
            let loadStart = CFAbsoluteTimeGetCurrent()
            // Explicitly the LLM factory: text-only benchmarking of checkpoints
            // that may carry a vision tower (see file header).
            let container = try await LLMModelFactory.shared.loadContainer(
                from: directory, using: #huggingFaceTokenizerLoader())
            print(String(
                format: "model loaded in %.1fs", CFAbsoluteTimeGetCurrent() - loadStart))

            let (modeCopy, enginesCopy, batchesCopy, stepsCopy, kvBytesCopy) =
                (options.mode, options.engines, options.batches, options.steps, options.kvBytes)
            let promptLengthsCopy = options.promptLengths
            let report: String = try await container.perform {
                (context: ModelContext) async throws -> String in
                var out = ""
                func emit(_ line: String) {
                    print(line)
                    out += line + "\n"
                }

                guard let hooks = v2Hooks(for: context.model) else {
                    throw CBv2KVError.backendIneligible(
                        reason: "model type \(type(of: context.model)) has no CBv2 hooks")
                }
                emit("model class: \(type(of: hooks.model)); layers: \(hooks.layerKinds.count)")
                let runR1 = MLX.GPU.gemma4ExpertQMMDiagnostics()
                let runOptimizations = RunOptimizationProvenance(
                    model: hooks.optimizations,
                    safeR1Requested: runR1.requested,
                    safeR1AOTAvailable: runR1.aotAvailable,
                    safeR1NAXAvailable: runR1.naxAvailable,
                    safeR1Effective:
                        hooks.optimizations.safeR1GeometryEligible
                        && runR1.requested && runR1.aotAvailable && !runR1.naxAvailable)
                emit("- optimization model: \(hooks.optimizations.markdown); "
                    + "safeR1(requested=\(runR1.requested), "
                    + "effective=\(runOptimizations.safeR1Effective), "
                    + "aot=\(runR1.aotAvailable), nax=\(runR1.naxAvailable))")
                emit("- optimization-run-json: \(try benchmarkJSONString(runOptimizations))")



                // Vocab probe ([1,1] cache-less forward) for synthetic prompts.
                // Use the exact model EngineV2 will drive so Gemma 4 VLM
                // checkpoints report and probe their owned text tower.
                let probe = hooks.model(MLXArray([Int32(0)]).reshaped(1, 1), cache: nil)
                let vocabSize = probe.dim(-1)
                emit("vocabSize=\(vocabSize)")

                // Chat prompt builder: the tokenizer's own chat template —
                // the same templating the production provider applies before
                // `submitTokenized` (the legacy BatchedEngine cascade died
                // with the v1 engine).
                let chatTokens: (String) -> [Int] = { question in
                    (try? context.tokenizer.applyChatTemplate(
                        messages: [["role": "user", "content": question]],
                        tools: nil, additionalContext: nil))
                        ?? context.tokenizer.encode(text: question, addSpecialTokens: true)
                }

                // Correctness ------------------------------------------------
                if modeCopy == "all" || modeCopy == "correctness" {
                    emit("\n## Correctness (v2 contiguous, greedy)\n")
                    let outcomes = await runCorrectness(
                        context: context, hooks: hooks, kvBytes: kvBytesCopy,
                        chatTokens: chatTokens, log: { emit($0) })
                    emit("")
                    for o in outcomes {
                        emit("- **\(o.name)**: \(o.pass ? "PASS" : "FAIL") — \(o.detail)")
                    }
                }

                // Profile ----------------------------------------------------
                // Phase-timer decomposition of the B=1 decode step. One warmup
                // cell absorbs kernel-compile costs; the measured cell then
                // runs with CBv2StepProfiler enabled. Only the contiguous
                // backend carries the phase timers, so every other engine is
                // refused out loud rather than skipped silently.
                if modeCopy == "profile" {
                    emit("\n## Decode-step profile (B=1, maxTokens \(stepsCopy))\n")
                    for engineName in enginesCopy {
                        guard resolveEngine(engineName) == .run(.contiguous) else {
                            emit("- \(engineName): not profilable — "
                                + "the phase timers only instrument v2 (contiguous)")
                            continue
                        }
                        _ = try? await runV2Cell(
                            context: context, hooks: hooks, backend: .contiguous,
                            batch: 1, promptLengths: [100], steps: 8,
                            vocabSize: vocabSize, kvBytes: kvBytesCopy)
                        CBv2StepProfiler.reset()
                        CBv2StepProfiler.enabled = true
                        let cell = try await runV2Cell(
                            context: context, hooks: hooks, backend: .contiguous,
                            batch: 1, promptLengths: [500], steps: stepsCopy,
                            vocabSize: vocabSize, kvBytes: kvBytesCopy,
                            trackOptimizationProvenance: true)
                        CBv2StepProfiler.enabled = false
                        emit("### v2 (contiguous) B=1 — decodeTPS "
                            + String(format: "%.1f", cell.decodeTPSPerRequest) + "\n")
                        emit(CBv2StepProfiler.summaryTable())
                        for line in try optimizationProvenanceLines(
                            cell, scope: "profile/v2/B1")
                        {
                            emit(line)
                        }
                    }
                }

                // Perf -------------------------------------------------------
                if modeCopy == "all" || modeCopy == "perf" {
                    // Performance mode never inherits opt-in phase clocks;
                    // profile mode above is the only timer-owning benchmark.
                    CBv2StepProfiler.enabled = false
                    emit("\n## Performance (maxTokens \(stepsCopy))\n")
                    var tableRows: [String] = []
                    var provenanceLines: [String] = []
                    var details: [String] = []
                    for engineName in enginesCopy {
                        // Every engine name resolves to exactly one of: a
                        // backend whose rawValue *is* the row label, or a
                        // refusal. There is no third path, so a row can never
                        // carry numbers produced by a different execution
                        // path than its label claims.
                        let backend: V2Backend
                        switch resolveEngine(engineName) {
                        case .refuse(let reason):
                            tableRows.append(refusalRow(engine: engineName, reason: reason))
                            continue
                        case .run(let resolved):
                            backend = resolved
                        }

                        // Warmup: absorb kernel compile / cache-shape costs.
                        // A warmup failure (paged backend ineligible on this
                        // model/hardware) refuses the whole engine rather than
                        // measuring a half-warmed one.
                        do {
                            _ = try await runV2Cell(
                                context: context, hooks: hooks, backend: backend,
                                batch: 1, promptLengths: [100], steps: 8,
                                vocabSize: vocabSize, kvBytes: kvBytesCopy)
                        } catch {
                            tableRows.append(refusalRow(
                                engine: engineName, reason: "skipped: \(error)"))
                            continue
                        }

                        for batch in batchesCopy {
                            let mix = promptMix(batch: batch, lengths: promptLengthsCopy)
                            let cell = try await runV2Cell(
                                context: context, hooks: hooks, backend: backend,
                                batch: batch, promptLengths: mix, steps: stepsCopy,
                                vocabSize: vocabSize, kvBytes: kvBytesCopy,
                                trackOptimizationProvenance: true)
                            tableRows.append(cell.markdownRow)
                            provenanceLines.append(
                                contentsOf: try optimizationProvenanceLines(
                                    cell, scope: "perf/\(engineName)/B\(batch)"))
                            details.append(String(
                                format: "    [mem after %@ B=%d] gpuActive=%.2f GiB gpuPeak=%.2f GiB",
                                cell.engine, batch,
                                Double(MLX.GPU.activeMemory) / Double(1 << 30),
                                Double(MLX.GPU.peakMemory) / Double(1 << 30)))
                            details.append(
                                "  \(cell.engine) B=\(batch):\n"
                                    + cell.perRequest.joined(separator: "\n"))
                        }
                    }
                    emit(performanceMarkdown(
                        rows: tableRows, provenanceLines: provenanceLines))
                    emit("\nPer-request detail:\n" + details.joined(separator: "\n"))
                }
                return out
            }

            let header = reportHeader(
                options: options, argv: argv,
                chip: sysctlString("machdep.cpu.brand_string"),
                ramGB: ProcessInfo.processInfo.physicalMemory / (1 << 30),
                osVersion: ProcessInfo.processInfo.operatingSystemVersionString,
                hostLine: contention.line, revision: buildRevision(), date: Date())
            if let outPath = options.outPath {
                try (header + report).write(
                    to: URL(fileURLWithPath: outPath), atomically: true, encoding: .utf8)
                print("report written to \(outPath)")
            }
            print("\nDONE")
        } catch {
            print("error: \(error)")
            exit(70)
        }
    }
}
